fn all_characters_same(s: &[u8]) -> bool {
    // An empty slice or a single‐element slice is trivially all the same.
    if s.len() < 2 {
        return true;
    }
    // Grab the first element and compare all others to it.
    let first = s[0];
    s.iter().all(|&b| b == first)
}

